tz_def('MANUAL_UDESC_51', 'محارب الهون هو العمود الفقري لمشاة الهون. رخيص الثمن وسريع التدريب، وهو جندي لائق من جميع النواحي للغارات المبكرة والدفاع الأساسي.');
